using System.Text.Json;
using Connapse.Eval.Metrics;
using FluentAssertions;

namespace Connapse.Eval.Tests.Metrics;

/// <summary>
/// Checks TableAnswerGrader against Fixtures/databench/expected.json: DataBench's own default_compare results
/// ("reference") and the Connapse rules ("connapse"), regenerated by generate_expected.py.
/// </summary>
[Trait("Category", "Unit")]
public class TableAnswerGraderFixtureTests
{
    private static readonly JsonElement Expected = JsonDocument.Parse(
        File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Fixtures", "databench", "expected.json"))).RootElement;

    public static TheoryData<int> Cases()
    {
        TheoryData<int> data = [];
        for (int i = 0; i < Expected.GetProperty("cases").GetArrayLength(); i++)
            data.Add(i);
        return data;
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void Grade_FixtureCase_MatchesConnapseRules(int index)
    {
        JsonElement c = Expected.GetProperty("cases")[index];

        bool graded = TableAnswerGrader.Grade(c.GetProperty("value"), c.GetProperty("truth"), c.GetProperty("type").GetString()!);

        graded.Should().Be(c.GetProperty("connapse").GetBoolean(), $"case {index}: {c}");
    }

    [Fact]
    public void Fixtures_EveryDeviationFromDataBench_HasAReason()
    {
        foreach (JsonElement c in Expected.GetProperty("cases").EnumerateArray())
        {
            bool differs = c.GetProperty("reference").GetBoolean() != c.GetProperty("connapse").GetBoolean();
            (c.GetProperty("deviation").ValueKind == JsonValueKind.String).Should().Be(differs, c.ToString());
        }
    }

    [Fact]
    public void Fixtures_CoverEveryTypeAndBothOutcomes()
    {
        List<JsonElement> cases = [.. Expected.GetProperty("cases").EnumerateArray()];

        foreach (string type in TableAnswerGrader.Types)
        {
            cases.Where(c => c.GetProperty("type").GetString()!.Trim() == type)
                .Select(c => c.GetProperty("connapse").GetBoolean())
                .Distinct().Should().HaveCount(2, type);
        }
    }
}

[Trait("Category", "Unit")]
public class TableAnswerGraderTests
{
    private static JsonElement J(string json) => JsonDocument.Parse(json).RootElement;

    private static bool G(string value, string truth, string type) => TableAnswerGrader.Grade(J(value), J(truth), type);

    [Theory]
    [InlineData("null", "null", true)]
    [InlineData("\"nan\"", "\"None\"", true)]
    [InlineData("\"[]\"", "[]", true)]
    [InlineData("null", "\"x\"", false)]
    [InlineData("\"x\"", "null", false)]
    [InlineData("\"np.nan\"", "\"x\"", false)]
    public void Grade_NullAnswers_MatchOnlyEachOther(string value, string truth, bool expected) =>
        G(value, truth, TableAnswerGrader.Category).Should().Be(expected);

    [Theory]
    [InlineData("true", "\"yes\"", true)]
    [InlineData("\" Y \"", "\"TRUE\"", true)]
    [InlineData("false", "\"n\"", true)]
    [InlineData("\"no\"", "\"yes\"", false)]
    [InlineData("\"yes\"", "\"no\"", false)]
    [InlineData("\"maybe\"", "\"maybe\"", false)]
    public void Grade_Boolean_UsesDataBenchWords(string value, string truth, bool expected) =>
        G(value, truth, TableAnswerGrader.Boolean).Should().Be(expected);

    [Theory]
    [InlineData("\"North  East\"", "\"north east\"", true)]
    [InlineData("\" 'Acme' \"", "\"ACME\"", true)]
    [InlineData("\"Acme\"", "\"Acme Ltd\"", false)]
    [InlineData("123", "\"123\"", true)]
    [InlineData("\"2016-12-22T23:59:59-05:00\"", "\"2016-12-22\"", true)]
    [InlineData("\"2016-12-22 00:00\"", "\"2016-12-22\"", true)]
    [InlineData("\"2016-12-22t08:00z\"", "\"2016-12-22\"", true)]
    [InlineData("\"2016-12-22\"", "\"2016-12-23\"", false)]
    [InlineData("\"Dec 22, 2016\"", "\"2016-12-22\"", false)]
    [InlineData("\"2016-12-22\"", "\"22/12/2016\"", false)]
    [InlineData("\"2016-02-30\"", "\"2016-03-01\"", false)]
    [InlineData("\"2016-12-22T24:00\"", "\"2016-12-22\"", false)]
    [InlineData("\"2016-12-22T10:60\"", "\"2016-12-22\"", false)]
    [InlineData("\"2016-12-22T10:30:60\"", "\"2016-12-22\"", false)]
    [InlineData("\"2016-12-22T10:30:59.5+0100\"", "\"2016-12-22\"", true)]
    public void Grade_Category_NormalizesCaseAndSpacesAndReadsIsoDates(string value, string truth, bool expected) =>
        G(value, truth, TableAnswerGrader.Category).Should().Be(expected);

    [Theory]
    [InlineData("100", "100", true)]
    [InlineData("100.4", "100", false)]
    [InlineData("\"100.0\"", "100", true)]
    [InlineData("\"$1,000\"", "1000", true)]
    [InlineData("99", "100.0", true)]
    [InlineData("98.99", "100.0", false)]
    [InlineData("101", "100.0", true)]
    [InlineData("101.02", "100.0", false)]
    [InlineData("-99", "-100.0", true)]
    [InlineData("-98.9", "-100.0", false)]
    [InlineData("0", "0.0", true)]
    [InlineData("0.0001", "0.0", false)]
    [InlineData("1000", "1e3", true)]
    [InlineData("1001", "1e3", true)]
    [InlineData("1011", "1e3", false)]
    [InlineData("\"1000.5\"", "\"1000\"", false)]
    [InlineData("\"1000.5\"", "\"1000.0\"", true)]
    [InlineData("\"abc\"", "1", false)]
    [InlineData("1", "\"abc\"", false)]
    [InlineData("\"1.2.3\"", "1.2", false)]
    [InlineData("\"5-\"", "5", false)]
    [InlineData("\"-.5\"", "-0.5", true)]
    [InlineData("true", "1", false)]
    public void Grade_Number_ExactForIntegersElseOnePercent(string value, string truth, bool expected) =>
        G(value, truth, TableAnswerGrader.Number).Should().Be(expected);

    [Theory]
    [InlineData("[\"b\", \"A\"]", "[\"a\", \"B\"]", true)]
    [InlineData("\"['b', 'a']\"", "[\"a\", \"b\"]", true)]
    [InlineData("[\"Smith, John\", \"Lee\"]", "[\"Lee\", \"Smith, John\"]", true)]
    [InlineData("[\"a\", \"a\", \"b\"]", "[\"a\", \"b\", \"b\"]", false)]
    [InlineData("[\"a\", \"b\"]", "[\"a\", \"b\", \"c\"]", false)]
    [InlineData("[\"a\", null]", "[\"a\", \"nan\"]", true)]
    [InlineData("[\"a\", \"\"]", "[\"a\", \"x\"]", false)]
    [InlineData("[\"2023-01-01T00:00:00Z\", \"2023-01-02\"]", "[\"2023-01-02\", \"2023-01-01\"]", true)]
    [InlineData("[\"2023-01-01\", \"2023-01-03\"]", "[\"2023-01-02\", \"2023-01-01\"]", false)]
    [InlineData("[\"2023-01-01\", \"x\"]", "[\"x\", \"2023-01-01\"]", true)]
    [InlineData("[1, 2]", "[\"2\", \"1\"]", true)]
    public void Grade_ListCategory_ComparesMultisets(string value, string truth, bool expected) =>
        G(value, truth, TableAnswerGrader.ListCategory).Should().Be(expected);

    [Theory]
    [InlineData("[3, 1, 2]", "[1, 2, 3]", true)]
    [InlineData("\"3, 1, 2\"", "[1, 2, 3]", true)]
    [InlineData("[1, 1, 2]", "[1, 2, 2]", false)]
    [InlineData("[1, 2]", "[1, 2, 3]", false)]
    [InlineData("[10.05, 20]", "[20, 10.0]", true)]
    [InlineData("[10.2, 20]", "[20, 10.0]", false)]
    [InlineData("[21, 10]", "[20, 10]", false)]
    [InlineData("[\"$1,000\", \" \", 2]", "[2, 1000]", true)]
    [InlineData("[\"x\", 2]", "[1, 2]", false)]
    [InlineData("[1, 2]", "[1, \"x\"]", false)]
    [InlineData("[-1.5, -3]", "[-3, -1.5]", true)]
    public void Grade_ListNumber_PairsSortedValues(string value, string truth, bool expected) =>
        G(value, truth, TableAnswerGrader.ListNumber).Should().Be(expected);

    [Fact]
    public void Grade_UnknownType_Throws()
    {
        Action act = () => G("1", "1", "date");

        act.Should().Throw<ArgumentException>().WithMessage("*date*");
    }

    [Fact]
    public void Grade_NullType_Throws()
    {
        Action act = () => TableAnswerGrader.Grade(J("1"), J("1"), null!);

        act.Should().Throw<ArgumentNullException>();
    }

    [Fact]
    public void Grade_TypeWithSpaces_IsTrimmed() => G("1", "1", " number ").Should().BeTrue();

    [Theory]
    [InlineData("Acme", "acme", TableAnswerGrader.Category, true)]
    [InlineData(null, null, TableAnswerGrader.Number, true)]
    [InlineData("1,2", null, TableAnswerGrader.ListNumber, false)]
    public void Grade_TextOverload_GradesLikeJsonStrings(string? value, string? truth, string type, bool expected) =>
        TableAnswerGrader.Grade(value, truth, type).Should().Be(expected);

    [Fact]
    public void ToText_FollowsPythonStr()
    {
        TableAnswerGrader.ToText(J("[\"a\", 1, null, true]")).Should().Be("['a', 1, None, True]");
        TableAnswerGrader.ToText(J("false")).Should().Be("False");
        TableAnswerGrader.ToText(J("null")).Should().BeNull();
        TableAnswerGrader.ToText(J("{\"a\": 1}")).Should().Be("{\"a\": 1}");
    }

    [Theory]
    [InlineData("12", 12.0, true)]
    [InlineData("12.0", 12.0, false)]
    [InlineData("1E2", 100.0, false)]
    [InlineData("\"-7\"", -7.0, true)]
    [InlineData("\"7.25%\"", 7.25, false)]
    public void TryNumber_ReadsValueAndWhetherItIsAnInteger(string json, double number, bool integral)
    {
        TableAnswerGrader.TryNumber(J(json), out double n, out bool i).Should().BeTrue();

        n.Should().Be(number);
        i.Should().Be(integral);
    }

    [Theory]
    [InlineData("null")]
    [InlineData("\"\"")]
    [InlineData("\"-\"")]
    public void TryNumber_NoNumber_ReturnsFalse(string json) =>
        TableAnswerGrader.TryNumber(J(json), out _, out _).Should().BeFalse();

    [Fact]
    public void Close_ToleranceBoundary_IsInclusive()
    {
        TableAnswerGrader.Close(101, 100, truthIsInteger: false).Should().BeTrue();
        TableAnswerGrader.Close(101.0001, 100, truthIsInteger: false).Should().BeFalse();
        TableAnswerGrader.Close(100, 100, truthIsInteger: true).Should().BeTrue();
        TableAnswerGrader.Close(100.0001, 100, truthIsInteger: true).Should().BeFalse();
    }

    /// <summary>Seeded random answers: every answer matches itself, and the text-only rules are symmetric.</summary>
    [Fact]
    public void Grade_RandomInputs_ReflexiveAndSymmetric()
    {
        Random rng = new(20261108);
        string[] words = ["Alpha", "beta Co", "North East", "q3", "ACME Ltd", "2024-02-29", "yes", "no", "n"];
        for (int i = 0; i < 2000; i++)
        {
            JsonElement number = J(Math.Round((rng.NextDouble() - 0.5) * 1e6, rng.Next(0, 4)).ToString("R", System.Globalization.CultureInfo.InvariantCulture));
            TableAnswerGrader.Grade(number, number, TableAnswerGrader.Number).Should().BeTrue(number.ToString());

            JsonElement a = JsonSerializer.SerializeToElement(words[rng.Next(words.Length)]);
            JsonElement b = JsonSerializer.SerializeToElement(words[rng.Next(words.Length)]);
            TableAnswerGrader.Grade(a, a, TableAnswerGrader.Category).Should().BeTrue();
            TableAnswerGrader.Grade(a, b, TableAnswerGrader.Category).Should().Be(TableAnswerGrader.Grade(b, a, TableAnswerGrader.Category));
            TableAnswerGrader.Grade(a, b, TableAnswerGrader.Boolean).Should().Be(TableAnswerGrader.Grade(b, a, TableAnswerGrader.Boolean));

            JsonElement list = JsonSerializer.SerializeToElement(Enumerable.Range(0, rng.Next(1, 6)).Select(_ => words[rng.Next(words.Length)]).ToArray());
            JsonElement shuffled = JsonSerializer.SerializeToElement(list.EnumerateArray().Select(e => e.GetString()).OrderBy(_ => rng.Next()).ToArray());
            TableAnswerGrader.Grade(shuffled, list, TableAnswerGrader.ListCategory).Should().BeTrue();

            JsonElement numbers = JsonSerializer.SerializeToElement(Enumerable.Range(0, rng.Next(1, 6)).Select(_ => Math.Round(rng.NextDouble() * 1000, 2)).ToArray());
            JsonElement reversed = JsonSerializer.SerializeToElement(numbers.EnumerateArray().Select(e => e.GetDouble()).Reverse().ToArray());
            TableAnswerGrader.Grade(reversed, numbers, TableAnswerGrader.ListNumber).Should().BeTrue();
        }
    }
}
